  knowledge_articles: [
    { id: 'kb-001', title: 'Memahami Perbedaan PKWT dan PKWTT di Lembaga Pendidikan', author: 'Rina Kartika, S.Psi., M.M.', category: 'industrial-relations', summary: 'Ringkasan praktis perbedaan perjanjian kerja waktu tertentu dan tidak tertentu serta implikasinya bagi yayasan pendidikan.', content: 'PKWT (Perjanjian Kerja Waktu Tertentu) adalah perjanjian berdasarkan jangka waktu atau pencapaian pekerjaan tertentu. Pada lembaga pendidikan, PKWT umumnya digunakan untuk guru honorer dengan jangka waktu satu tahun ajaran dan dapat diperpanjang, dengan catatan total durasi tidak melebihi ketentuan peraturan (maksimal 5 tahun).\n\nPKWTT (Perjanjian Kerja Waktu Tidak Tertentu) mengikat pegawai tanpa batas waktu, memberi kepastian masa kerja, hak cuti tahunan, jaminan sosial, dan proteksi PHK lebih kuat. Pegawai yang kriteria PKWT-nya terpenuhi namun diperpanjang terus tanpa klarifikasi berisiko dianggap PKWTT secara hukum.\n\nPraktik yang direkomendasikan: (1) klasifikasi posisi mana yang cocok PKWT vs PKWTT dalam Pedoman Manajemen SDM; (2) gunakan template kontrak terverifikasi; (3) catat tanggal akhir kontrak di sistem; (4) lakukan evaluasi kinerja sebelum perpanjangan.', references: 'UU No. 13 Tahun 2003; PP No. 35 Tahun 2021; Pedoman Manajemen SDM Yayasan v2.1.', status: 'dipublikasikan', published_at: '2026-08-10', created_by: 'u-mhrd', created_at: '2026-08-10T02:00:00Z' },
    { id: 'kb-002', title: 'Manajemen Kinerja Guru: dari KPI sampai Remunerasi', author: 'Dr. Siti Nurhaliza, M.Pd.', category: 'performance-mgmt', summary: 'Membangun siklus manajemen kinerja guru yang objektif: penetapan indikator, monitoring, dan kaitan dengan pengembangan.', content: 'Manajemen kinerja guru yang sehat dimulai dari penetapan indikator yang jelas di awal tahun: KPI (Key Performance Indicator) untuk capaian strategis unit dan IKI (Individu Key Indicator) untuk tugas spesifik guru, misalnya kualitas modul ajar, kehadiran, dan pengembangan diri.\n\nMonitoring tengah tahun membantu deteksi dini kesulitan, bukan untuk menghukum. Penilaian akhir tahun dilakukan dengan formulir standar dan dibahas dalam sesi umpan balik dua arah.\n\nHasil penilaian digunakan untuk: program pelatihan (Training Need Analysis), pemetaan talenta, penugasan tambahan, dan remunerasi kinerja. Prinsip penting: transparansi kriteria dan konsistensi penerapan antar unit pendidikan.', references: 'Pedoman Penilaian Kinerja HR-POL-005; Template KPI/IKI TPL-IN-002.', status: 'dipublikasikan', published_at: '2026-09-05', created_by: 'u-dirdik', created_at: '2026-09-05T02:00:00Z' },
    { id: 'kb-003', title: 'HR Analytics untuk Yayasan Pendidikan: Mulai dari Data yang Ada', author: 'Yusuf Maulana, S.A.', category: 'hr-analytics', summary: 'Cara sederhana memanfaatkan data kepegawaian yang sudah dimiliki HRD untuk pengambilan keputusan.', content: 'HR analytics tidak harus rumit. Mulailah dari empat metrik dasar: (1) rasio pegawai tetap vs kontrak; (2) tingkat perputaran (turnover) per unit; (3) rata-rata hari cuti terpakai; (4) biaya pelatihan per pegawai.\n\nData sumbernya sudah ada: rekap presensi, dokumen kontrak, laporan penggajian, dan sertifikat pelatihan. Konsolidasikan pada dasbor bulanan dan bahas dalam rapat HRD.\n\nManfaat praktis: memprediksi kebutuhan pengisian guru saat pensiun/undur diri, menilai efektivitas program pelatihan, dan menyusun argumen berbasis data saat membahas kesejahteraan dengan pimpinan yayasan.', references: 'Laporan HRD Triwulan; Dokumentasi modul HR Knowledge Center.', status: 'dipublikasikan', published_at: '2026-07-22', created_by: 'u-kabid', created_at: '2026-07-22T02:00:00Z' },
    { id: 'kb-004', title: 'Tata Kelola SDM Boarding School: Tantangan dan Solusi', author: 'H. Muhammad Ridwan, S.H.', category: 'boarding-school', summary: 'Karakteristik pengelolaan pegawai di lingkungan asrama pendidikan dan kerangka kebijakan yang disarankan.', content: 'Boarding school memiliki karakter pegawai unik: jam kerja panjang, tugas pendampingan asrama (musyrif/musyrifah), dan batasan interaksi. Tanpa kebijakan jelas, beban kerja tidak terukur dan risiko kelelahan tinggi.\n\nKerangka kebijakan yang disarankan: (1) uraian tugas khusus musyrif terpisah dari tugas mengajar; (2) pola shift pendampingan yang jelas dengan ganti hari; (3) tunjangan pendampingan terpisah dari gaji pokok; (4) kode etik khusus lingkungan asrama; (5) mekanisme pembinaan dan pelaporan isu asrama yang aman.\n\nSemua kebijakan tetap berlandaskan UU Ketenagakerjaan: waktu kerja, istirahat, dan hak cuti tetap wajib dipenuhi.', references: 'UU No. 13 Tahun 2003; PP No. 35 Tahun 2021.', status: 'dipublikasikan', published_at: '2026-06-15', created_by: 'u-pembina', created_at: '2026-06-15T02:00:00Z' },
    { id: 'kb-005', title: 'Onboarding Pegawai Baru: 30 Hari Pertama yang Menentukan', author: 'Dewi Lestari, S.E.', category: 'manajemen-sdm', summary: 'Checklist orientasi pegawai baru yayasan pendidikan agar produktivitas dan rasa memiliki cepat terbangun.', content: '30 hari pertama menentukan retensi pegawai. Checklist yang terbukti efektif:\n\nHari 1-2: orientasi organisasi (sejarah yayasan, struktur, budaya), penyerahan kartu BPJS, akun aplikasi.\nMinggu 1: pembekalan kebijakan utama (peraturan kepegawaian, kode etik, presensi), penjelasan KPI.\nMinggu 2-3: pendampingan oleh mentor rekan kerja (buddy), observasi kelas/mekanisme kerja.\nMinggu 4: evaluasi awal bersama atasan dan kesepakatan target 90 hari.\n\nDokumentasikan setiap tahap menggunakan Formulir Evaluasi Pegawai agar data onboarding tersimpan rapi di HR Knowledge Center.', references: 'SOP Pengangkatan Pegawai SOP-HRD-002.', status: 'dipublikasikan', published_at: '2026-10-12', created_by: 'u-kabid', created_at: '2026-10-12T02:00:00Z' },
    { id: 'kb-006', title: 'Kepatuhan BPJS bagi Yayasan Pendidikan Swasta', author: 'Rina Kartika, S.Psi., M.M.', category: 'comp-benefits', summary: 'Kewajiban jaminan sosial pegawai yayasan: cakupan program, iuran, dan risiko ketidakpatuhan.', content: 'Yayasan sebagai pemberi kerja wajib mendaftarkan pegawai ke BPJS Kesehatan (khusus kelas/asrama kesehatan pegawai) dan BPJS Ketenagakerjaan (program JKK, JKM, JHT; pensiun untuk PKWTT).\n\nIuran dibagi antara yayasan dan pegawai sesuai ketentuan, dan harus dipotong serta disetor tepat waktu melalui sistem penggajian. Kegagalan mendaftarkan pegawai berisiko sanksi administratif dan gugatan saat terjadi kecelakaan kerja.\n\nPraktik terbaik: integrasikan pendaftaran BPJS dalam SOP pengangkatan pegawai, lakukan rekonsiliasi iuran bulanan, dan arsipkan kartu digital pegawai pada folder kepegawaian terbatas.', references: 'UU No. 24 Tahun 2011; SOP BPJS SOP-HRD-006.', status: 'dipublikasikan', published_at: '2026-05-30', created_by: 'u-mhrd', created_at: '2026-05-30T02:00:00Z' },
  ],

